"""Build identity shared with the compiled frontend, generated by Vite."""
import json
from pathlib import Path


def read_build_info():
    try:
        data = json.loads(Path(__file__).with_name("site_build.json").read_text())
        if not isinstance(data, dict) or not all(isinstance(data.get(k), str) and data[k]
                for k in ("version", "buildId", "builtAt")):
            return None
        return {k: data.get(k) for k in ("version", "buildId", "builtAt", "revision", "dirty")}
    except (OSError, ValueError):
        return None
